66	export async function CreateSheafModelRegistry(
67	  config: SheafChatConfig,
68	  authStorage: AuthStorage,
69	  options: CreateSheafModelRegistryOptions = {},
70	): Promise<SheafModelRegistryBundle>
71	{
72	  const modelsJsonPath = ResolveSheafModelsJsonPath(config);
73	  const modelRegistry = ModelRegistry.create(authStorage, modelsJsonPath);
74	  const localProviderState =
75	    options.localProviderState ?? await FetchLocalModels(config, options);
76	
77	  if (config.openAiApiKey !== null)
78	  {
79	    authStorage.setRuntimeApiKey("openai", config.openAiApiKey);
80	  }
