96	export function MapPiModelToMetadata(
97	  model: PiRegistryModel,
98	  config: SheafChatConfig,
99	  modelRegistry: ModelRegistry,
100	  localProviderState: LocalProviderState,
101	): ModelMetadata
102	{
103	  const available =
104	    model.provider === x_localProviderName
105	      ? IsLocalModelAvailable(config, localProviderState) &&
106	        localProviderState.models.some((entry) => entry.id === model.id)
107	      : modelRegistry.hasConfiguredAuth(model);
108	
109	  const metadata: ModelMetadata = {
110	    provider: model.provider,
111	    id: model.id,
112	    displayName: model.name ?? model.id,
113	    contextTokens:
114	      typeof model.contextWindow === "number" && Number.isFinite(model.contextWindow)
115	        ? model.contextWindow
116	        : undefined,
117	    available,
118	  };
119	
120	  if (!available && model.provider === x_localProviderName)
121	  {
122	    metadata.unavailableReason =
123	      localProviderState.unavailableReason ?? x_localFetchFailedReason;
124	  }
125	
126	  return metadata;
127	}
