129	export function ListModels(
130	  config: SheafChatConfig,
131	  modelRegistry: ModelRegistry,
132	  localProviderState: LocalProviderState,
133	): ModelMetadata[]
134	{
135	  const models = modelRegistry.getAll();
136	  const metadata = models.map((model) =>
137	    MapPiModelToMetadata(model, config, modelRegistry, localProviderState));
138	
139	  const seen = new Set<string>();
140	  const merged: ModelMetadata[] = [];
141	
142	  for (const entry of metadata)
143	  {
144	    const key = `${entry.provider}:${entry.id}`;
145	    if (seen.has(key))
146	    {
147	      continue;
148	    }
149	
150	    seen.add(key);
151	    merged.push(entry);
152	  }
153	
154	  merged.sort((left, right) =>
155	  {
156	    const providerCompare = left.provider.localeCompare(right.provider);
157	    if (providerCompare !== 0)
158	    {
159	      return providerCompare;
160	    }
161	
162	    return left.id.localeCompare(right.id);
163	  });
164	
165	  return merged;
166	}
