168	export function ValidateModelSelection(
169	  config: SheafChatConfig,
170	  modelRegistry: ModelRegistry,
171	  localProviderState: LocalProviderState,
172	  selection: ModelReference,
173	): ModelMetadata
174	{
175	  const model = modelRegistry.find(selection.provider, selection.id);
176	
177	  if (model === undefined)
178	  {
179	    throw new ModelValidationError(
180	      "model_not_found",
181	      `model not found: ${selection.provider}/${selection.id}`,
182	    );
183	  }
184	
185	  const metadata = MapPiModelToMetadata(
186	    model,
187	    config,
188	    modelRegistry,
189	    localProviderState,
190	  );
191	
192	  if (!metadata.available)
193	  {
194	    throw new ModelValidationError(
195	      "model_unavailable",
196	      metadata.unavailableReason
197	        ? `model unavailable: ${metadata.unavailableReason}`
198	        : `model unavailable: ${selection.provider}/${selection.id}`,
199	    );
200	  }
201	
202	  return metadata;
203	}
