1	/**
2	 * Model registry - manages built-in and custom models, provides API key resolution.
3	 */
4	import { type Api, type AssistantMessageEventStream, type Context, type Model, type OAuthProviderInterface, type SimpleStreamOptions } from "@earendil-works/pi-ai";
5	import type { AuthStatus, AuthStorage } from "./auth-storage.ts";
6	import { clearConfigValueCache } from "./resolve-config-value.ts";
7	export type ResolvedRequestAuth = {
8	    ok: true;
9	    apiKey?: string;
10	    headers?: Record<string, string>;
11	} | {
12	    ok: false;
13	    error: string;
14	};
15	/** Clear the config value command cache. Exported for testing. */
16	export declare const clearApiKeyCache: typeof clearConfigValueCache;
17	/**
18	 * Model registry - loads and manages models, resolves API keys via AuthStorage.
19	 */
20	export declare class ModelRegistry {
21	    private models;
22	    private providerRequestConfigs;
23	    private modelRequestHeaders;
24	    private registeredProviders;
25	    private loadError;
26	    readonly authStorage: AuthStorage;
27	    private modelsJsonPath;
28	    private constructor();
29	    static create(authStorage: AuthStorage, modelsJsonPath?: string): ModelRegistry;
30	    static inMemory(authStorage: AuthStorage): ModelRegistry;
31	    /**
32	     * Reload models from disk (built-in + custom from models.json).
33	     */
34	    refresh(): void;
35	    /**
36	     * Get any error from loading models.json (undefined if no error).
37	     */
38	    getError(): string | undefined;
39	    private loadModels;
40	    /** Load built-in models and apply provider/model overrides */
41	    private loadBuiltInModels;
42	    /** Merge custom models into built-in list by provider+id (custom wins on conflicts). */
43	    private mergeCustomModels;
44	    private loadCustomModels;
45	    private validateConfig;
46	    private parseModels;
47	    /**
48	     * Get all models (built-in + custom).
49	     * If models.json had errors, returns only built-in models.
50	     */
51	    getAll(): Model<Api>[];
52	    /**
53	     * Get only models that have auth configured.
54	     * This is a fast check that doesn't refresh OAuth tokens.
55	     */
56	    getAvailable(): Model<Api>[];
57	    /**
58	     * Find a model by provider and ID.
59	     */
60	    find(provider: string, modelId: string): Model<Api> | undefined;
61	    /**
62	     * Get API key for a model.
63	     */
64	    hasConfiguredAuth(model: Model<Api>): boolean;
65	    private getModelRequestKey;
66	    private storeProviderRequestConfig;
67	    private storeModelHeaders;
68	    /**
69	     * Get API key and request headers for a model.
70	     */
71	    getApiKeyAndHeaders(model: Model<Api>): Promise<ResolvedRequestAuth>;
72	    /**
73	     * Return auth status for a provider, including request auth configured in models.json.
74	     * This intentionally does not execute command-backed config values.
75	     */
76	    getProviderAuthStatus(provider: string): AuthStatus;
77	    /**
78	     * Get display name for a provider.
79	     */
80	    getProviderDisplayName(provider: string): string;
81	    /**
